evidence, bad = {}, []
for t in D["topics"]:
    ev = {}
    for c, v in t[2].items():
        if not v:
            continue
        if (t[0], c) in OVR:
            q = OVR[(t[0], c)]
            e = ("Завдання" if v == 2 else "Згадка") + f": «{q}»"
        else:
            e = evidence_for(rows[c], t[0], v)
            q = e.split("«", 1)[1].rstrip("»").rstrip("…") if e else None
        if q and find_quote(pages[c], q[:160]) is None:
            bad.append((t[0], c, q[:60]))
        if e:
            ev[c] = e
    if t[0] == "T13":
        for c in ("ОК1.1", "ОК1.2", "ОК1.3"):
            ev[c] = "У назві курсу «скульптура», але в «Описі» й «Короткому змісті» немає жодного завдання з ліплення чи об'ємного моделювання."
    evidence[t[0]] = ev

