def esc(x):
    return _html.escape(str(x))


def abroad_cards():
    cards = []
    for x in S.SALARIES_ABROAD:
        lad = ""
        if x["ladl"]:
            lad = '<div class="ladder">' + "".join(f'<div>{esc(l)}<b>{esc(v)}</b></div>' for l, v in zip(x["ladl"], x["lad"])) + "</div>"
        src = "; ".join(f'<a href="{esc(u)}" target="_blank" rel="noopener">{esc(t)}</a>' for u, t in x["src"])
        h3 = "Фриланс" if x["country"] == "Віддалено" else "Дизайнер інтер'єру"
        cards.append(f'<div class="role abroad"><span class="eyebrow">{esc(x["country"])} · {esc(x["role"])}</span><h3>{h3}</h3><div class="med">{esc(x["med"])}</div>'
                     f'<div class="small muted">{esc(x["per"])}</div>{lad}<p class="small">{esc(x["note"])}</p><p class="small muted">{src}</p></div>')
    return "".join(cards)


NU = sum(N.values())
def skills_joint():
    line_sk = {x[0]: (i, x) for i, x in enumerate(D["skills"])}
    out = []
    for c, n in S.SKILLS + S.CONTEXT_SKILLS:
        ua = round(sum(SHU[c][k] * N[k] for k in N) / NU)
        fz = SHA[c]
        tot = round((ua * NU + fz * NA) / (NU + NA))
        if n in line_sk:
            i, x = line_sk[n]
            out.append(dict(n=n, ua=ua, fz=fz, tot=tot, line=True, now=x[3], after=x[5], w=skill_where[i]))
        else:
            out.append(dict(n=n, ua=ua, fz=fz, tot=tot, line=False))
    out.sort(key=lambda r: -r["tot"])
    return out


def vacancies_html():
    vac = "".join(f'<li>{esc(v[0])} — <a href="{esc(v[1])}" target="_blank" rel="noopener">{esc(v[1][:90])}</a> · {", ".join(v[2])}</li>' for v in S.VACANCIES_ABROAD)
    return f"""<details class="card"><summary><b>Вибірка закордонних оголошень · {NA}</b></summary><ol class="small">{vac}</ol>
    <p class="small muted">Фрагменти оголошень з текстом вимог у результатах пошуку, станом на {S.AS_OF}. Мала вибірка — частки орієнтовні.</p></details>"""


